import { test, expect } from '@playwright/test';

test.describe('Promo Code Expiration Error Handling', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/checkout');
  });

  test('should display error message when user enters expired promo code', async ({ page }) => {
    // Setup: intercept the API call to validate promo code
    await page.route('**/api/promo-codes/validate', (route) => {
      route.abort('failed');
    });

    // Setup: intercept the API call to get promo details
    await page.route('**/api/promo-codes/details', (route) => {
      route.abort('failed');
    });

    // Setup: intercept the API call to apply discount
    await page.route('**/api/checkout/apply-discount', (route) => {
      route.abort('failed');
    });

    // Setup: intercept the API call to complete checkout
    await page.route('**/api/checkout/complete', (route) => {
      route.abort('failed');
    });

    // Get the promo code input using getByLabel
    const promoCodeInput = page.getByLabel('Promo Code');
    await expect(promoCodeInput).toBeVisible();

    // Enter an expired promo code
    await promoCodeInput.fill('EXPIRED123');

    // Get the error message using getByText
    const errorMessage = page.getByText('Promo code has expired');
    await expect(errorMessage).toBeVisible();

    // Verify error message is displayed
    await expect(errorMessage).toContainText('Promo code has expired');

    // Verify checkout button is disabled
    const checkoutButton = page.getByRole('button', { name: /checkout/i });
    await expect(checkoutButton).toBeDisabled();

    // Verify error message is visible and styled appropriately
    await expect(errorMessage).toHaveClass(/error-message/);

    // Verify promo code input is still visible
    await expect(promoCodeInput).toBeVisible();
  });

  test('should clear error message when user enters a valid promo code', async ({ page }) => {
    // Setup: intercept the API call to validate promo code
    await page.route('**/api/promo-codes/validate', (route) => {
      route.continue();
    });

    // Setup: intercept the API call to get promo details
    await page.route('**/api/promo-codes/details', (route) => {
      route.continue();
    });

    // Setup: intercept the API call to apply discount
    await page.route('**/api/checkout/apply-discount', (route) => {
      route.continue();
    });

    // Setup: intercept the API call to complete checkout
    await page.route('**/api/checkout/complete', (route) => {
      route.continue();
    });

    // Get the promo code input using getByLabel
    const promoCodeInput = page.getByLabel('Promo Code');
    await expect(promoCodeInput).toBeVisible();

    // Enter a valid promo code
    await promoCodeInput.fill('VALID2023');

    // Get the success message using getByText
    const successMessage = page.getByText('Promo applied successfully');
    await expect(successMessage).toBeVisible();

    // Verify success message is displayed
    await expect(successMessage).toContainText('Promo applied successfully');

    // Verify error message is no longer visible
    const errorMessage = page.getByText('Promo code has expired');
    await expect(errorMessage).not.toBeVisible();

    // Verify checkout button is now enabled
    const checkoutButton = page.getByRole('button', { name: /checkout/i });
    await expect(checkoutButton).toBeEnabled();

    // Verify error message is cleared
    await expect(errorMessage).not.toBeVisible();
  });
});
